import{_ as r,o as t,c as a,a3 as o}from"./chunks/framework.BWzgKoSO.js";const c=JSON.parse('{"title":"附 E　来源全表","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/e-sources.md","filePath":"appendix/e-sources.md","lastUpdated":1793533698000}'),n={name:"appendix/e-sources.md"};function s(i,e,g,l,h,p){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="附-e-来源全表" tabindex="-1">附 E　来源全表 <a class="header-anchor" href="#附-e-来源全表" aria-label="Permalink to &quot;附 E　来源全表&quot;">​</a></h1><p>这里放正文里所有编号的完整条目。每一条我都点到过原文，能点的都会给出链接。</p><h2 id="怎么读这张表" tabindex="-1">怎么读这张表 <a class="header-anchor" href="#怎么读这张表" aria-label="Permalink to &quot;怎么读这张表&quot;">​</a></h2><p><strong>等级</strong>：<strong>A</strong> 官方指南、国标、系统综述或大样本随机对照试验　<strong>B</strong> 单项随机对照试验、队列研究　<strong>C</strong> 机制推断、小样本、个人经验</p><p><strong>编号</strong>：G 是官方文件，R 是论文与研究，S 是平台与产品数据。</p><p>正文里只写编号，是为了让段落能读下去。你要核的时候来这里。</p><h2 id="g-系列-官方文件" tabindex="-1">G 系列　官方文件 <a class="header-anchor" href="#g-系列-官方文件" aria-label="Permalink to &quot;G 系列　官方文件&quot;">​</a></h2><p><strong>G1｜《成人肥胖食养指南（2024 年版）》</strong>〔A〕 国家卫生健康委员会，2024 年 2 月发布。 用到的地方：0.2 每周减重的速度上限；2.2 缺口 500～1000 千卡与男女下限；2.4 三大营养素供能比与三餐 3:4:3；3.3 进餐顺序；3.7 油盐上限；4.2 运动处方与久坐时间；6.2 平台期是标准情形；8.4 乳母要在指导下减重。 原文位置：能量与供能比在正文第 5 页；进餐顺序在第 8 页；运动处方在第 8 页；减重速度在第 9 页。 链接：<a href="https://www.nhc.gov.cn/sps/c100088/202402/9ba512ba8e314a47a181db11d2fa188d/files/1743476136267_20714.pdf" target="_blank" rel="noreferrer">https://www.nhc.gov.cn/sps/c100088/202402/9ba512ba8e314a47a181db11d2fa188d/files/1743476136267_20714.pdf</a></p><p><strong>G2｜《中国居民膳食指南（2022）》</strong>〔A〕 中国营养学会编著，人民卫生出版社。 用到的地方：3.4 每日饮水量（男 1700 毫升、女 1500 毫升，准则六）；3.5 与 3.7 食盐不超过 5 克、烹调油 25～30 克（准则四）；4.6 每天主动身体活动 6000 步（准则二）；3.11 成年人饮酒一天酒精不超过 15 克、哪些人不应饮酒、哪些情况应控制饮酒（驾车、服用与酒精相互作用的药物、酒精过敏、高甘油三酯血症、胰腺炎、肝病、血尿酸过高）（准则五）；8.4 乳母不应饮酒（准则五）。 链接：<a href="http://dg.cnsoc.org/article/04/wDCyy7cWSJCN6pwKHOo5Dw.html" target="_blank" rel="noreferrer">http://dg.cnsoc.org/article/04/wDCyy7cWSJCN6pwKHOo5Dw.html</a> 准则五链接：<a href="http://dg.cnsoc.org/article/04/ApX3_ozGTmSoqQaFFh5z_Q.html" target="_blank" rel="noreferrer">http://dg.cnsoc.org/article/04/ApX3_ozGTmSoqQaFFh5z_Q.html</a></p><p><strong>G3｜GB 28050《预包装食品营养标签通则》</strong>〔A〕 现行版本 GB 28050-2011；新版 GB 28050-2025 于 2025 年 3 月 16 日发布，2027 年 3 月 16 日实施，替代 2011 版。 用到的地方：1.7 与 3.5 的“无糖”“无能量”判定线。 含量声称的阈值（两版一致）：无糖 ≤0.5 克/100 克（或 100 毫升）；低糖 ≤5 克/100 克；无脂肪 ≤0.5 克/100 克；低脂肪 固体 ≤3 克/100 克、液体 ≤1.5 克/100 毫升；无能量 ≤17 千焦/100 克（或 100 毫升），且脂肪供能比 ≤50%。 新版另有一处值得知道的变化：强制标示从“1+4”升级为“1+6”，增加了饱和脂肪（酸）和糖。</p><p><strong>G4｜《美国居民膳食指南（2025—2030）》</strong>〔A〕 美国农业部与卫生与公众服务部。 用到的地方：3.2 蛋白质目标 1.2～1.6 克/公斤体重/天（按个人热量需求调整）。 链接：<a href="https://cdn.realfood.gov/DGA.pdf" target="_blank" rel="noreferrer">https://cdn.realfood.gov/DGA.pdf</a></p><p><strong>G5｜《Use of non-sugar sweeteners: WHO guideline》</strong>〔A〕 世界卫生组织，2023 年 5 月。 用到的地方：1.7 不建议把非糖甜味剂当作控制体重的手段。 链接：<a href="https://www.who.int/publications/i/item/9789240073616" target="_blank" rel="noreferrer">https://www.who.int/publications/i/item/9789240073616</a></p><p><strong>G6｜美国国家医学院（IOM）膳食营养素参考摄入量：碳水 RDA 130 克/天</strong>〔A〕 Dietary Reference Intakes for Energy, Carbohydrate, Fiber, Fat, Fatty Acids, Cholesterol, Protein, and Amino Acids，2005 年，第 6 章。依据是大脑每天需要的葡萄糖量。 用到的地方：2.4 碳水底线。</p><p><strong>G7｜《中国食物成分表》第 6 版</strong>〔B〕 杨月欣主编，北京大学医学出版社，2018 年。 用到的地方：2.4 与 3.1 的换算式。 关键条目：米饭（蒸）每 100 克 116 千卡，蛋白质 2.6 克，脂肪 0.3 克，碳水 25.9 克；馒头每 100 克 223 千卡。</p><p><strong>G8｜《成人体重判定》WS/T 428-2013</strong>〔A〕 国家卫生和计划生育委员会发布。 用到的地方：2.8 与 4.1。BMI 24～27.9 为超重、≥28 为肥胖；腰围男性 ≥90 厘米、女性 ≥85 厘米为中心型肥胖。</p><p><strong>G9｜《肥胖症诊疗指南（2024 年版）》</strong>〔A〕 国家卫生健康委员会，2024 年 10 月。 用到的地方：2.8 BMI 的局限（年龄与体脂、运动员）、肥胖分级、腰围与腰臀比的警戒线、体脂比阈值、儿童青少年用百分位、3～6 个月减 5%～15% 并维持、减重期防肌少症；7.1 减重期与维持期的有氧处方；7.3 术后“比最低点反弹超 15%”算体重反弹；8.3 两药的适应证、剂量、禁忌、副作用、停药反弹、肌少性肥胖。 原文位置：BMI 分级、腰围与体脂比在第 5～6 页；治疗目标与减重速率在第 23 页；运动处方（减重期 150～420 分钟、维持期 200～300 分钟、抗阻每周 2～3 次取 50%～70% 最大负荷）在第 28 页；GLP-1 停药反弹与肌少性肥胖在第 39～40 页；司美格鲁肽与替尔泊肽条目在第 36～38 页。 链接：<a href="https://www.nhc.gov.cn/wjw/c100378/202410/bcf804e19e0c4246b5aea6cd338b55e1/files/1732873189749_61795.pdf" target="_blank" rel="noreferrer">https://www.nhc.gov.cn/wjw/c100378/202410/bcf804e19e0c4246b5aea6cd338b55e1/files/1732873189749_61795.pdf</a></p><p><strong>G10｜诺和盈与穆峰达在中国的获批与上市</strong>〔A〕 诺和盈（减重版司美格鲁肽）：2024 年 6 月 25 日获国家药监局批准减重适应症，2024 年 11 月 17 日上市。适应症门槛 BMI ≥30，或 BMI 27～30 且至少一种体重相关合并症。 穆峰达（替尔泊肽）：2024 年 5 月获批糖尿病适应症，2024 年 7 月 19 日获批减重适应症，2025 年 1 月 2 日上市。减重门槛 BMI ≥28，或 BMI ≥24 且至少一种合并症。 用到的地方：8.3。</p><p><strong>G11｜T/CNSS 014—2022《产褥期妇女膳食指导》</strong>〔A〕 中国营养学会发布，2022 年 8 月 30 日发布、10 月 30 日实施。 用到的地方：8.4 产褥期哺乳与不哺乳的能量推荐（哺乳 9614 kJ/d，即 2300 kcal/d；非哺乳 7524 kJ/d，即 1800 kcal/d）、“食不过量”、产后运动的时间和强度、每日睡眠 8 小时以上。 原文位置：5.1.1.1；能量推荐表；5.5.1；5.5.2.1。 链接：<a href="https://www.cnsoc.org/otherNotice/files/@CmsXh_e27ba247-10af-42b5-96e7-41e99ef4ece6.pdf" target="_blank" rel="noreferrer">https://www.cnsoc.org/otherNotice/files/@CmsXh_e27ba247-10af-42b5-96e7-41e99ef4ece6.pdf</a></p><p><strong>G12｜FAO《Food energy – methods of analysis and conversion factors》</strong>〔A〕 联合国粮农组织，Food and Nutrition Paper 77，2003 年，第 3 章。 用到的地方：3.11 酒精每克约 7 千卡（29 kJ/g；未取整为 6.9 kcal/g），以及蛋白质、碳水 4 千卡、脂肪 9 千卡的通用系数。 链接：<a href="https://www.fao.org/4/y5022e/y5022e04.htm" target="_blank" rel="noreferrer">https://www.fao.org/4/y5022e/y5022e04.htm</a></p><p><strong>G13｜2023 年多囊卵巢综合征国际循证指南</strong>〔A〕 Teede HJ, Tay CT, Laven JSE, Dokras A, 等. Recommendations From the 2023 International Evidence-based Guideline for the Assessment and Management of Polycystic Ovary Syndrome. <em>J Clin Endocrinol Metab</em>. 2023;108(10):2447-2469. DOI：<a href="https://doi.org/10.1210/clinem/dgad463" target="_blank" rel="noreferrer">https://doi.org/10.1210/clinem/dgad463</a> 全文：<a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC10505534/" target="_blank" rel="noreferrer">https://pmc.ncbi.nlm.nih.gov/articles/PMC10505534/</a> 用到的地方：8.4 患病率 10%～13%（1.6.1）；月经不规律的判断线（1.1.1）；进食障碍（2.5.1）；生活方式干预推荐给所有患者、体重没掉也有好处（3.1.1、3.1.5）；没有哪种饮食结构更优（3.3.1）；运动量（3.4 节）。</p><p><strong>G14｜《多囊卵巢综合征中国诊疗指南》</strong>〔A〕 中华医学会妇产科学分会内分泌学组及指南专家组. 中华妇产科杂志, 2018, 53(1): 2-6. DOI：10.3760/cma.j.issn.0529-567X.2018.01.002 全文：<a href="http://cmab.yiigle.com/uploads/guide_html/%E5%A4%9A%E5%9B%8A%E5%8D%B5%E5%B7%A2%E7%BB%BC%E5%90%88%E5%BE%81%E4%B8%AD%E5%9B%BD%E8%AF%8A%E7%96%97%E6%8C%87%E5%8D%97.html" target="_blank" rel="noreferrer">http://cmab.yiigle.com/uploads/guide_html/多囊卵巢综合征中国诊疗指南.html</a> 用到的地方：8.4 疑似与确诊的诊断条件；生活方式干预是首选基础治疗；运动每天 30 分钟、每周至少 5 次。另：全文未出现“体重下降 5%～10% 使 80% 以上患者恢复排卵”一类表述，网上转述不实。</p><p><strong>G15｜ACOG Committee Opinion No. 804：孕期与产后的身体活动和运动</strong>〔A〕 American College of Obstetricians and Gynecologists. Physical Activity and Exercise During Pregnancy and the Postpartum Period. <em>Obstet Gynecol</em>. 2020;135(4):e178-e188. DOI：<a href="https://doi.org/10.1097/AOG.0000000000003772" target="_blank" rel="noreferrer">https://doi.org/10.1097/AOG.0000000000003772</a> 用到的地方：8.4 身体活动可能是预防产后抑郁的重要因素（摘要原文）。</p><h2 id="r-系列-论文与研究" tabindex="-1">R 系列　论文与研究 <a class="header-anchor" href="#r-系列-论文与研究" aria-label="Permalink to &quot;R 系列　论文与研究&quot;">​</a></h2><p><strong>R1｜局部肌肉训练对局部脂肪的影响</strong>〔B〕 Ramírez-Campillo R, Andrade DC, Campos-Jara C, Henríquez-Olguín C, Alvarez-Lepín C, Izquierdo M. Regional fat changes induced by localized muscle endurance resistance training. <em>J Strength Cond Res</em>. 2013;27:2219-2224. DOI：<a href="https://doi.org/10.1519/JSC.0b013e31827e8681" target="_blank" rel="noreferrer">https://doi.org/10.1519/JSC.0b013e31827e8681</a> 样本 11 人，只练一条腿，12 周、每周 3 次。练的那条腿脂肪无显著变化，全身脂肪降 5.1%。</p><p><strong>R2｜六周腹部训练</strong>〔B〕 Vispute SS, Smith JD, LeCheminant JD, Hurley KS. The effect of abdominal exercise on abdominal fat. <em>J Strength Cond Res</em>. 2011;25(9):2559-2564. DOI：<a href="https://doi.org/10.1519/JSC.0b013e3181fb4a46" target="_blank" rel="noreferrer">https://doi.org/10.1519/JSC.0b013e3181fb4a46</a> 样本 24 人，7 个腹部动作、2 组 10 次、每周 5 天、共 6 周。体重、体脂率、腰围、腹部皮褶均无显著变化，卷腹次数显著增加。</p><p><strong>R3｜饮食记录里的低报</strong>〔B〕 Poslusna K, Ruprich J, de Vries JHM, Jakubikova M, van&#39;t Veer P. Misreporting of energy and micronutrient intake estimated by food records and 24 hour recalls, control and adjustment methods in practice. <em>Br J Nutr</em>. 2009;101(S2):S73-S85. DOI：<a href="https://doi.org/10.1017/S0007114509990602" target="_blank" rel="noreferrer">https://doi.org/10.1017/S0007114509990602</a> 纳入 37 项研究，系统讨论低报的规模、成因与识别方法。</p><p><strong>R4｜TREAT：限时进食 vs 单纯限热量</strong>〔A〕 Liu D, et al. Calorie Restriction with or without Time-Restricted Eating in Weight Loss. <em>N Engl J Med</em>. 2022;386(16):1495-1504. DOI：<a href="https://doi.org/10.1056/NEJMoa2114833" target="_blank" rel="noreferrer">https://doi.org/10.1056/NEJMoa2114833</a></p><p><strong>R5｜16:8 的 12 周试验</strong>〔A〕 Lowe DA, et al. Effects of Time-Restricted Eating on Weight Loss and Other Metabolic Parameters in Women and Men With Overweight and Obesity. <em>JAMA Intern Med</em>. 2020;180(11):1491. DOI：<a href="https://doi.org/10.1001/jamainternmed.2020.4153" target="_blank" rel="noreferrer">https://doi.org/10.1001/jamainternmed.2020.4153</a></p><p><strong>R6｜Cochrane：间歇性断食</strong>〔A〕 Garegnani LI, Oltra G, Ivaldi D, 等. Intermittent fasting for adults with overweight or obesity. <em>Cochrane Database Syst Rev</em>. 2026;2:CD015610. DOI：<a href="https://doi.org/10.1002/14651858.CD015610.pub2" target="_blank" rel="noreferrer">https://doi.org/10.1002/14651858.CD015610.pub2</a> 说明：编号 CD015610 在 2023 年先出过一版方案（protocol），带结论的正式版是 2026 年 2 月这版。网上流传的“2025 年 Cochrane 那篇”，多半指的就是这个系列。</p><p><strong>R7｜BMJ 网状 meta 分析：各种断食方案</strong>〔A〕 Semnani-Azad Z, Khan TA, Chiavaroli L, 等. Intermittent fasting strategies and their effects on body weight and other cardiometabolic risk factors: systematic review and network meta-analysis of randomised clinical trials. <em>BMJ</em>. 2025;389:e082007. DOI：<a href="https://doi.org/10.1136/bmj-2024-082007" target="_blank" rel="noreferrer">https://doi.org/10.1136/bmj-2024-082007</a> 99 项随机试验、6,582 人。与持续限热量相比，只有隔日禁食有减重优势：平均多减 1.29 公斤（95% CI −1.99 至 −0.59）。</p><p><strong>R8｜Mifflin-St Jeor 公式</strong>〔B〕 Mifflin MD, St Jeor ST, Hill LA, Scott BJ, Daugherty SA, Koh YO. A new predictive equation for resting energy expenditure in healthy individuals. <em>Am J Clin Nutr</em>. 1990;51:241-247. DOI：<a href="https://doi.org/10.1093/ajcn/51.2.241" target="_blank" rel="noreferrer">https://doi.org/10.1093/ajcn/51.2.241</a> 样本 498 人。男：10×体重＋6.25×身高－5×年龄＋5；女：10×体重＋6.25×身高－5×年龄－161。</p><p><strong>R9｜餐前喝水</strong>〔B〕 Dennis EA, Dengo AL, Comber DL, 等. Water Consumption Increases Weight Loss During a Hypocaloric Diet Intervention in Middle-aged and Older Adults. <em>Obesity</em>. 2010;18(2):300-307. DOI：<a href="https://doi.org/10.1038/oby.2009.235" target="_blank" rel="noreferrer">https://doi.org/10.1038/oby.2009.235</a> 48 人，55～75 岁，BMI 25～40。餐前 500 毫升水＋低热量饮食 12 周，比只做低热量饮食的那组多减约 2 公斤。</p><p><strong>R10｜碳循环</strong>〔C〕 把 “carbohydrate cycling” 当主题词检索，没有找到针对减重结局的随机对照试验。此编号代表“查过、没有”，不是一条文献。 用到的地方：3.9。</p><p><strong>R11｜先吃菜再吃主食对血糖的影响</strong>〔B〕 Kampmann-Gongoll K, Schlesinger S, Noreik M, Kuss O, Lang A. Effect of eating vegetables before carbohydrates on glucose, insulin and glycemic control — a systematic review and meta-analysis of randomized controlled trials. <em>Clin Nutr</em>. 2026;66:106775. DOI：<a href="https://doi.org/10.1016/j.clnu.2026.106775" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.clnu.2026.106775</a> 18 项随机试验。餐后 30 分钟与 60 分钟的血糖、胰岛素确实降低，但 10 项被评为中等偏倚风险、8 项为高风险，证据确定性“很低”。</p><p><strong>R12｜极端减重后的长期代谢适应</strong>〔B〕 Fothergill E, Guo J, Howard L, 等. Persistent metabolic adaptation 6 years after “The Biggest Loser” competition. <em>Obesity</em>. 2016;24:1612-1619. DOI：<a href="https://doi.org/10.1002/oby.21538" target="_blank" rel="noreferrer">https://doi.org/10.1002/oby.21538</a> 16 人参赛，6 年后 14 人回访。比赛结束时平均减 58.3 公斤；6 年后回来 41.0 公斤；静息消耗比按体重推算的低 499 千卡/天。</p><p><strong>R13｜STEP-1 与它的停药延伸研究</strong>〔A／B〕 主体：Wilding JPH, 等. Once-Weekly Semaglutide in Adults with Overweight or Obesity. <em>N Engl J Med</em>. 2021;384(11):989-1002. DOI：<a href="https://doi.org/10.1056/NEJMoa2032183%EF%BC%8868" target="_blank" rel="noreferrer">https://doi.org/10.1056/NEJMoa2032183（68</a> 周平均减 14.9%，安慰剂组 2.4%） 延伸：Wilding JPH, 等. Weight regain and cardiometabolic effects after withdrawal of semaglutide: The STEP 1 trial extension. <em>Diabetes Obes Metab</em>. 2022;24:1553-1564. DOI：<a href="https://doi.org/10.1111/dom.14725%EF%BC%88327" target="_blank" rel="noreferrer">https://doi.org/10.1111/dom.14725（327</a> 人，治疗期平均减 17.3%，停药一年回来 11.6 公斤）</p><p><strong>R14｜SURMOUNT-1 与 SURMOUNT-4</strong>〔A／B〕 主体：Jastreboff AM, 等. Tirzepatide Once Weekly for the Treatment of Obesity. <em>N Engl J Med</em>. 2022;387(3):205-216. DOI：<a href="https://doi.org/10.1056/NEJMoa2206038%EF%BC%8872" target="_blank" rel="noreferrer">https://doi.org/10.1056/NEJMoa2206038（72</a> 周平均减 15%～21%） 停药：Aronne LJ, 等. Continued Treatment With Tirzepatide for Maintenance of Weight Reduction in Adults With Obesity: The SURMOUNT-4 Trial. <em>JAMA</em>. 2024. DOI：<a href="https://doi.org/10.1001/jama.2023.24945%EF%BC%88%E5%85%88%E7%94%A8" target="_blank" rel="noreferrer">https://doi.org/10.1001/jama.2023.24945（先用</a> 36 周降 20.9%；之后继续用药再降 5.5%，换安慰剂回升 14.0%）</p><p><strong>R15｜步频提高 5%～10% 对关节负荷的影响</strong>〔B〕 Heiderscheit BC, Chumanov ES, Michalski MP, Wille CM, Ryan MB. Effects of step rate manipulation on joint mechanics during running. <em>Med Sci Sports Exerc</em>. 2011;43(2):296-302. DOI：<a href="https://doi.org/10.1249/MSS.0b013e3181ebedf4" target="_blank" rel="noreferrer">https://doi.org/10.1249/MSS.0b013e3181ebedf4</a> 45 名跑者在不同步频下测关节力学。步频在自选步频基础上提高 5%～10%，髋、膝的关节负荷与下肢冲击下降，步幅缩短。注意：研究支持的是“相对自己的步频往上调一点”，不是“必须 180 步/分”。 用到的地方：4.7。</p><p><strong>R16｜改落地方式值不值：系统综述</strong>〔B〕 Anderson LM, Bonanno DR, Hart HF, Barton CJ. What are the Benefits and Risks Associated with Changing Foot Strike Pattern During Running? A Systematic Review and Meta-analysis of Injury, Running Economy, and Biomechanics. <em>Sports Med</em>. 2020;50(5):885-917. DOI：<a href="https://doi.org/10.1007/s40279-019-01238-y" target="_blank" rel="noreferrer">https://doi.org/10.1007/s40279-019-01238-y</a> 纳入 53 项研究。改成前脚掌落地：膝关节屈曲幅度与髌股关节应力下降，但踝关节跖屈肌负荷上升；跑步经济性没有改善证据；受伤风险只有回顾性证据，缺前瞻性研究，关系无法确定。作者结论：对没有受伤、习惯后跟着地的跑者，不建议改落地方式。所以不必刻意改，但要避免落脚点过度前伸。 用到的地方：4.7。</p><p><strong>R17｜耐力训练的强度分布：三区模型</strong>〔B〕 Seiler S. What is Best Practice for Training Intensity and Duration Distribution in Endurance Athletes? <em>Int J Sports Physiol Perform</em>. 2010;5(3):276-291. DOI：<a href="https://doi.org/10.1123/ijspp.5.3.276" target="_blank" rel="noreferrer">https://doi.org/10.1123/ijspp.5.3.276</a> 三区划分：一区在第一乳酸阈以下，二区介于两个乳酸阈之间，三区在第二阈以上。综述汇编的观察：高水平耐力选手约 80% 的训练课落在低强度（约 2 毫摩尔/升血乳酸），约 20% 是高强度间歇（约 90% VO2max）；中间那块反而不多，这就是后来常说的极化训练。注意：这里的“二区”和手表五区的“二区”不是一个东西。 用到的地方：4.8。</p><p><strong>R18｜最大心率怎么估</strong>〔B〕 Tanaka H, Monahan KD, Seals DR. Age-predicted maximal heart rate revisited. <em>J Am Coll Cardiol</em>. 2001;37(1):153-156. DOI：<a href="https://doi.org/10.1016/S0735-1097(00)01054-8" target="_blank" rel="noreferrer">https://doi.org/10.1016/S0735-1097(00)01054-8</a> 在对 351 项研究的汇总分析基础上给出：最大心率 ≈ 208 − 0.7×年龄。比 220−年龄 的误差小，但仍是估算，个体差异可达 ±10 次/分左右。 用到的地方：4.8。</p><p><strong>R19｜乳酸阈的概念与取值</strong>〔B〕 Faude O, Kindermann W, Meyer T. Lactate Threshold Concepts: How Valid are They? <em>Sports Med</em>. 2009;39(6):469-490. DOI：<a href="https://doi.org/10.2165/00007256-200939060-00003" target="_blank" rel="noreferrer">https://doi.org/10.2165/00007256-200939060-00003</a> 综述固定与个体乳酸阈两类方法。常用的两个坐标：第一乳酸阈约 2 毫摩尔/升，第二乳酸阈约 4 毫摩尔/升。 用到的地方：4.8。</p><p><strong>R20｜说话测试作为强度标记</strong>〔B〕 Foster C, Porcari JP, Anderson J, Paulson M, Smaczny D, Webber H, 等. The Talk Test as a Marker of Exercise Training Intensity. <em>J Cardiopulm Rehabil Prev</em>. 2008;28(1):24-30. DOI：<a href="https://doi.org/10.1097/01.HCR.0000311504.41775.78" target="_blank" rel="noreferrer">https://doi.org/10.1097/01.HCR.0000311504.41775.78</a> 能完整说话对应中等强度以下/中等强度，说话开始受限的位置接近通气阈。不需要设备。 用到的地方：4.8、4.9。</p><p><strong>R21｜各项运动的能耗区间（MET 值）</strong>〔A〕 Ainsworth BE, Haskell WL, Herrmann SD, Meckes N, 等. 2011 Compendium of Physical Activities: a second update of codes and MET values. <em>Med Sci Sports Exerc</em>. 2011;43(8):1575-1581. DOI：<a href="https://doi.org/10.1249/MSS.0b013e31821ece12" target="_blank" rel="noreferrer">https://doi.org/10.1249/MSS.0b013e31821ece12</a> 运动能耗研究里通用的编码表，每一项给一个 MET 值（安静坐着约为 1）。本书用到的区间：平地快走 4.3，上坡走 5.3 到 8.0，上楼梯 8.8，慢跑 7.0 到 9.8，骑行 6.8 到 8.0，跳绳 11.0 到 12.3，自重力量 3.5 到 8.0，跳操 6.5 到 8.0，自由泳 5.8 到 9.8，器械训练 3.5 到 6.0。换算成消耗是 70 公斤的人一小时约 MET × 70 千卡，属于估算，个体差异可达两三成。 用到的地方：4.11。</p><p><strong>R22｜月经周期里自觉水肿的变化</strong>〔B〕 White CP, Hitchcock CL, Vigna YM, Prior JC. Fluid Retention over the Menstrual Cycle: 1-Year Data from the Prospective Ovulation Cohort. <em>Obstet Gynecol Int</em>. 2011;2011:138451. DOI：<a href="https://doi.org/10.1155/2011/138451" target="_blank" rel="noreferrer">https://doi.org/10.1155/2011/138451</a> 62 位健康女性、765 个周期的每日日记。自评水肿在经期第一天最高，卵泡期中段最低。记的是自我感觉，没有称体重。 用到的地方：8.4。</p><p><strong>R23｜月经周期里的能量摄入</strong>〔C〕 Rogan MM, Black KE. Dietary energy intake across the menstrual cycle: a narrative review. <em>Nutr Rev</em>. 2023;81(7):869-886. DOI：<a href="https://doi.org/10.1093/nutrit/nuac094" target="_blank" rel="noreferrer">https://doi.org/10.1093/nutrit/nuac094</a> 叙述性综述。卵泡期摄入偏低、黄体期偏高，幅度目前无法量化，个体之间、周期之间都有差异；作者明确指出高质量研究缺乏。 用到的地方：8.4。</p><p><strong>R24｜月经周期对静息代谢的影响</strong>〔A〕 Benton MJ, Hutchins AM, Dawes JJ. Effect of menstrual cycle on resting metabolism: A systematic review and meta-analysis. <em>PLoS One</em>. 2020;15(7):e0236025. DOI：<a href="https://doi.org/10.1371/journal.pone.0236025" target="_blank" rel="noreferrer">https://doi.org/10.1371/journal.pone.0236025</a> 26 项研究、318 位女性。黄体期静息代谢略高，效应量小（ES＝0.33）；2000 年以后的研究里不再显著（ES＝0.23，p＝0.055）。样本小，偏倚风险不低。 用到的地方：8.4。</p><p><strong>R25｜哺乳期减重对婴儿生长的影响</strong>〔B〕 Lovelady CA, Garner KE, Moreno KL, Williams JP. The Effect of Weight Loss in Overweight, Lactating Women on the Growth of Their Infants. <em>N Engl J Med</em>. 2000;342(7):449-453. DOI：<a href="https://doi.org/10.1056/NEJM200002173420701" target="_blank" rel="noreferrer">https://doi.org/10.1056/NEJM200002173420701</a> 40 位产后 4 周、BMI 25～30、纯母乳喂养的女性随机分组，10 周。饮食加运动组减 4.8±1.7 公斤，对照组 0.8±2.3 公斤；婴儿生长无差别。 用到的地方：8.4。</p><p><strong>R26｜喝酒会不会让人少吃饭：系统综述与 meta 分析</strong>〔A〕 Kwok A, Dordevic AL, Paton G, Page MJ, 等. Effect of alcohol consumption on food energy intake: a systematic review and meta-analysis. <em>Br J Nutr</em>. 2019;121(5):481-495. DOI：<a href="https://doi.org/10.1017/S0007114518003677" target="_blank" rel="noreferrer">https://doi.org/10.1017/S0007114518003677</a> 22 项研究、701 人。饮酒组食物摄入多 343 kJ（95% CI 161～525），总摄入多 1072 kJ（820～1323）。受试者多为 18～37 岁，部分结果异质性大。千焦换千卡按 4.184 算。 用到的地方：3.11。</p><p><strong>R27｜酒精、食欲与能量平衡</strong>〔B〕 Yeomans MR. Alcohol, appetite and energy balance: Is alcohol intake a risk factor for obesity? <em>Physiol Behav</em>. 2010;100(1):82-89. DOI：<a href="https://doi.org/10.1016/j.physbeh.2010.01.012" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.physbeh.2010.01.012</a> 综述：酒精的热量是叠加上去的；饭前或饭时喝酒倾向于增加进食。 用到的地方：3.11。</p><p><strong>R28｜和别人一起吃会吃得更多：系统综述与 meta 分析</strong>〔A〕 Ruddock HK, Brunstrom JM, Vartanian LR, Higgs S. A systematic review and meta-analysis of the social facilitation of eating. <em>Am J Clin Nutr</em>. 2019;110(4):842-861. DOI：<a href="https://doi.org/10.1093/ajcn/nqz155" target="_blank" rel="noreferrer">https://doi.org/10.1093/ajcn/nqz155</a> 42 项研究。与朋友一起吃比独自吃选得多、吃得多；效应受同桌者熟悉程度影响。 用到的地方：3.11。</p><h2 id="s-系列-平台与产品" tabindex="-1">S 系列　平台与产品 <a class="header-anchor" href="#s-系列-平台与产品" aria-label="Permalink to &quot;S 系列　平台与产品&quot;">​</a></h2><p><strong>S1｜麦当劳中国巨无霸营养信息</strong>〔A〕 每份能量 2146 千焦，约 513 千卡；蛋白质 27 克，脂肪 26 克，碳水 42 克，钠 961 毫克。 链接：<a href="https://www.mcdonalds.com.cn/product/Big-Mac" target="_blank" rel="noreferrer">https://www.mcdonalds.com.cn/product/Big-Mac</a> 用到的地方：1.6、2.2。</p><p><strong>S2｜Free Exercise DB（动作示范照片）</strong>〔B〕 yuhonas/free-exercise-db，870 余个动作，每个动作两张照片（起始、到位），数据集以 Unlicense 释出，属公有领域，可自由使用与改写。 链接：<a href="https://github.com/yuhonas/free-exercise-db" target="_blank" rel="noreferrer">https://github.com/yuhonas/free-exercise-db</a> 用到的地方：4.4 与 4.10 的 29 张分解图。我把每个动作的起止两帧拼成一张，加了标号与要点；照片本身没有改动动作、没有重绘。</p><h2 id="作者自己那一份" tabindex="-1">作者自己那一份 <a class="header-anchor" href="#作者自己那一份" aria-label="Permalink to &quot;作者自己那一份&quot;">​</a></h2><p>第零部分、第五部分里关于减重经历的叙述，第一人称，来自本人；体重、体脂、BMI 的数字取自体脂秤截图，两张截图都在第零部分。</p><p><strong>我没有做的</strong>：这本书里没有一项数据是我自己测的。体重之外的身体成分、代谢指标、训练量，我一个都没测过。所以凡是讲到“我怎么做的”，只到我确实做过的那一步为止。</p><h2 id="怎么自己核" tabindex="-1">怎么自己核 <a class="header-anchor" href="#怎么自己核" aria-label="Permalink to &quot;怎么自己核&quot;">​</a></h2><p>官方文件去卫健委官网或中国营养学会官网找，都是免费 PDF。</p><p>论文用 DOI 打开，摘要里的“结果”“结论”两段必看。免费全文在 PubMed Central、Europe PMC 上找。</p><p>找不到原文、只看到转述，就把那条当线索，不当依据。</p><hr><p>这篇附录会长，但它比正文更该被挑刺。哪一条点不开、哪一句和原文对不上，去仓库提 issue，我改。</p>',63)])])}const m=r(n,[["render",s]]);export{c as __pageData,m as default};
